// Set unit test configuration by changing the value in comment:
// 
// SOURCE_FILE = index.html
// BROWSER_HEADLESS = true

QUnit.test('Test labels for radio buttons', function(assert) {
   const fieldSet = document.querySelector('form fieldset');
   if (fieldSet === null) {
      assert.ok(false, 'Status <fieldset> exists');
   }

   // Find radio buttons
   const radioBtns = fieldSet.querySelectorAll('input[type=radio]');
   assert.equal(radioBtns.length, 2, 'Number of radio button <input> elements in first <fieldset>');

   // Find labels
   const labels = fieldSet.querySelectorAll('label');
   assert.equal(labels.length, 2, 'Number of <label> elements in first <fieldset>');

   // Label can surround radio button or be separated, so accept either way
   if (radioBtns[0].parentElement.tagName === 'LABEL') {
      assert.equal(radioBtns[0].parentElement.tagName.toLowerCase(), 'label', 'First radio button has <label> parent');
      assert.equal(radioBtns[0].parentElement.innerText.trim(), 'Draft', 'First radio button label text');
   }
   else {
      // Test label's for attribute
      const labelFor = labels[0].getAttribute('for');
      assert.ok(labelFor !== null, 'First <label> has a "for" attribute');
      const radioId = radioBtns[0].getAttribute('id');
      assert.ok(radioId !== null, 'First radio button has an "id" attribute');
      assert.equal(labelFor, radioId, 'First label\'s "for" attribute value matches first radio button\'s id');

      // Make sure label comes AFTER radio button
      if (radioBtns[0].previousElementSibling === null) {
         assert.ok(false, 'Element before first radio button <input> is <legend>');
      }
      const prevElement = radioBtns[0].previousElementSibling.tagName.toLowerCase();
      assert.equal(prevElement, 'legend', 'Element before first radio button <input> element');
      const nextElement = radioBtns[0].nextElementSibling.tagName.toLowerCase();
      assert.equal(nextElement, 'label', 'Element after first radio button <input> element');
   }

   if (radioBtns[1].parentElement.tagName === 'LABEL') {
      assert.equal(radioBtns[1].parentElement.tagName.toLowerCase(), 'label', 'Second radio button has <label> parent');   
      assert.equal(radioBtns[1].parentElement.innerText.trim(), 'Final', 'Second radio button label text');
   }
   else {
      // Test label's for attribute
      const labelFor = labels[1].getAttribute("for");
      assert.ok(labelFor !== null, 'Second <label> has a "for" attribute');
      const radioId = radioBtns[1].getAttribute("id");
      assert.ok(radioId !== null, 'Second radio button has an "id" attribute');
      assert.equal(labelFor, radioId, 'Second label\'s "for" attribute value matches second radio button\'s id');

      // Make sure label comes AFTER radio button
      if (radioBtns[1].nextElementSibling === null) {
         assert.ok(false, 'Element after second radio button <input> is <label>');
      }
      const prevElement = radioBtns[1].previousElementSibling.tagName.toLowerCase();
      assert.equal(prevElement, 'label', 'Element before second radio button <input> element');
      const nextElement = radioBtns[1].nextElementSibling.tagName.toLowerCase();
      assert.equal(nextElement, 'label', 'Element after second radio button <input> element');
   }
});

