QUnit.test('Test drop-down option elements', function(assert) {
   const dates = ['March 20', 'March 24', 'April 2', 'April 6', 'April 13'];

   let options = document.querySelectorAll('select option');
   assert.equal(options.length, dates.length, 'Number of <option> elements in <select>');

   // Use if statements to shorten amount of feedback in unit tests
   for (let i = 0; i < dates.length; i++) {
      if (options[i].value !== dates[i]) {
         assert.equal(options[i].value, dates[i], '<option> ' + (i+1) + ' value');
      }

      if (options[i].innerText !== dates[i]) {
         assert.equal(options[i].innerText, dates[i], '<option> ' + (i+1) + ' text');
      }
   }

   assert.ok(true, 'All <option> values and text are correct');
});

