QUnit.test('Test checkbox label elements', function(assert) {
   const names = ['Aarav Agarwal', 'Ava Johnson', 'Julio Ortiz', 'Liam Rubio', 'Emma Witherspoon'];

   let checkboxes = document.querySelectorAll('fieldset input[type=checkbox]');
   assert.equal(checkboxes.length, names.length, 'Number of checkbox <input> elements in <fieldset>');

   // Use if statements to shorten amount of feedback in unit tests
   for (let i = 0; i < checkboxes.length; i++) {
      // Allow label around checkbox or separated from checkbox
      if (checkboxes[i].parentElement.tagName === 'LABEL') {
         if (checkboxes[i].parentElement.tagName.toLowerCase() !== 'label') {
            assert.equal(checkboxes[i].parentElement.tagName.toLowerCase(), 'label', 
               'Checkbox <input> ' + (i+1) + ' has <label> parent');
         }

         if (checkboxes[i].parentElement.innerText !== names[i]) {
            assert.equal(checkboxes[i].parentElement.innerText, names[i], 
               'Checkbox <input> ' + (i+1) + ' label text');
         }
      }
      else {
         // Find checkbox id         
         const id = checkboxes[i].getAttribute("id");

         // Use if statements to reduce amount of test feedback
         if (id === null) {
            assert.ok(id !== null, 'Checkbox has an "id" attribute');
         }

         // Verify no spaces exist in the ID
         if (id.search(/\s/) !== -1) {
            assert.ok(false, `Checkbox's id attribute "${id}" contains NO spaces`);
         }

         // Find label that matches checkbox id
         const label = document.querySelector(`form label[for='${id}']`);
         if (label === null) {
            assert.ok(label !== null, `Label has "for" attribute that matches checkbox id "${id}"`);
         }

         const labelAdjacent = document.querySelector(`#${id} + label[for='${id}']`);
         if (labelAdjacent === null) {
            assert.ok(labelAdjacent !== null, `Checkbox's label is in front of checkbox with id "${id}"`);
         }
         if (label.innerText !== names[i]) {
            assert.equal(label.innerText, names[i], `Checkbox <input> ${i+1} label text`);
         }
      }
   }

   assert.ok(true, 'All checkbox <input> elements have corresponding <label> elements');

});

