QUnit.test('Test submit button', function(assert) {

   // Allow <button> and <input type="submit"> for backwards compatibility with previous version
   // of this lab. The previous version had some incorrect instructions, so this new one replaces it.

   const submitBtns = document.querySelectorAll('form button');
   const altSubmitBtns = document.querySelectorAll('form input[type=submit]');
   if (submitBtns.length === 0 && altSubmitBtns.length === 0) {
      assert.ok(false, 'Single submit <button> exists');
   }
   else if (submitBtns.length === 0 && altSubmitBtns.length === 1) {
      assert.ok(true, 'Single submit <input> button exists');
      assert.equal(altSubmitBtns[0].value, 'Submit', 'Submit button is labeled correctly');
   }
   else {
      assert.ok(submitBtns.length === 1, 'Single submit <button> exists');
      assert.equal(submitBtns[0].innerText, 'Submit', 'Submit button is labeled correctly');
   }
});
